test_that("log_lik for location shift models works as expected", {
  withr::local_seed(3L)
  brms_setup("log_lik:4",
    ns <- 25
  )
  brms_setup("log_lik:5",
    prep <- structure(list(), class = "brmsprep")
  )
  brms_setup("log_lik:6",
    prep$dpars <- list(
      mu = matrix(rnorm(ns * 2), ncol = 2),
      sigma = rchisq(ns, 3), nu = rgamma(ns, 4)
    )
  )
  brms_setup("log_lik:10",
    prep$family <- gaussian()
  )
  brms_setup("log_lik:11",
    prep$family$fun <- "gaussian"
  )
  brms_setup("log_lik:12",
    prep$data <- list(Y = rnorm(ns))
  )
  brms_setup("log_lik:14",
    ll_gaussian <- dnorm(
      x = prep$data$Y[1], mean = prep$dpars$mu[, 1],
      sd = prep$dpars$sigma, log = TRUE
    )
  )
  brms_setup("log_lik:18",
    ll <- brms_adapt_log_lik("gaussian", 1, prep = prep)
  )
  brms_port("log_lik:19", "pass",
    "",
    expect_equal(ll, ll_gaussian)
  )
  brms_setup("log_lik:21",
    ll_student <- dstudent_t(
      x = prep$data$Y[2], df = prep$dpars$nu,
      mu = prep$dpars$mu[, 2],
      sigma = prep$dpars$sigma, log = TRUE
    )
  )
  brms_setup("log_lik:26",
    ll <- brms_adapt_log_lik("student", 2, prep = prep)
  )
  brms_port("log_lik:27", "pass",
    "",
    expect_equal(ll, ll_student)
  )
  brms_setup("log_lik:30",
    prep$data$weights <- sample(1:10, ns, replace = TRUE)
  )
  brms_setup("log_lik:31",
    ll <- brms_adapt_log_lik("gaussian", 1, prep = prep)
  )
  brms_port("log_lik:32", "hollow",
    paste0(
      "holds, but tests the adapter: the assertion is brms's ",
      "log_lik_weight(), ll * weights[i], and the adapter computes ",
      "that product itself (dev/brmsport-bin2-adapters.R), because ",
      "frmtmb weights a row outside the family, in the objective ",
      "and in log_lik() of a fit. The weighted value is not ",
      "frmtmb's answer here, so it is not a pass. Removing the ",
      "adapter's weights line breaks it ",
      "(dev/remeasure-rev-noweights.txt), which shows exactly that"),
    expect_equal(ll, ll_gaussian * prep$data$weights[1])
  )
})

