test_that("log_lik for bernoulli and beta models works correctly", {
  withr::local_seed(352L)
  brms_setup("log_lik:353",
    ns <- 15
  )
  brms_setup("log_lik:354",
    nobs <- 10
  )
  brms_setup("log_lik:355",
