  )
  brms_setup("log_lik:356",
    prep$dpars <- list(
      mu = inv_logit(matrix(rnorm(ns * nobs * 2), ncol = nobs * 2)),
      phi = rgamma(ns, 4)
    )
  )
  brms_setup("log_lik:360",
    prep$data <- list(Y = sample(0:1, nobs, replace = TRUE))
  )
  brms_setup("log_lik:362",
    i <- sample(1:nobs, 1)
  )
  brms_setup("log_lik:363",
    ll_bern <- dbinom(
      x = prep$data$Y[i], prob = prep$dpars$mu[, i], size = 1, log = TRUE
    )
  )
  brms_setup("log_lik:366",
    ll <- brms_adapt_log_lik("bernoulli", i, prep = prep)
  )
  brms_port("log_lik:367", "pass",
    "",
    expect_equal(ll, ll_bern)
  )
  brms_setup("log_lik:369",
    prep$data <- list(Y = rbeta(nobs, 1, 1))
  )
  brms_setup("log_lik:370",
    ll_beta <- dbeta(
      x = prep$data$Y[i], shape1 = prep$dpars$mu[, i] * prep$dpars$phi,
      shape2 = (1 - prep$dpars$mu[, i]) * prep$dpars$phi, log = TRUE
